mapper.select:
SELECT * FROM (
    SELECT , CANCELED_YN FROM DOC_REGISTRY
     WHERE REG_YEAR = #{year}
       AND (DEPT_NAME = #{dept} OR HANDLER_ID = #{loginId} OR REGISTERED_BY = #{loginId})
       AND REG_TYPE = #{type}
       AND (TITLE LIKE '%' || #{q} || '%' OR REG_NO LIKE '%' || #{q} || '%'
                                 OR COUNTERPART LIKE '%' || #{q} || '%')
     ORDER BY REG_DATE DESC, REG_ID DESC
) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE DOC_REGISTRY SET

    TITLE = #{value}
    COUNTERPART = #{value}
    COUNTERPART_NO = #{value}
    MEDIUM = #{value}
    PAGES = #{pages, jdbcType=NUMERIC}
    RETENTION = #{value}
    DISCLOSURE = #{value}
    NOTE = #{value}
    CANCELED_YN = 'Y'
    REG_ID = REG_ID

 WHERE REG_ID = #{regId}
